-- 调拨出库单无价/带价打印模板（v277）。
-- 安全范围：仅更新租户 1、module_key=stock_transfer_out 的两条同名模板；
-- 不删除模板、不修改业务单据、不修改菜单/角色/权限。
-- 无价版仍显示合计金额；两版均显示明细件数和调出件数合计。
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

DROP PROCEDURE IF EXISTS apply_erp_stock_transfer_out_print_templates_v277;
DELIMITER $$

CREATE PROCEDURE apply_erp_stock_transfer_out_print_templates_v277()
BEGIN
  DECLARE no_price_json LONGTEXT;
  DECLARE with_price_json LONGTEXT;
  DECLARE no_price_paper LONGTEXT;
  DECLARE with_price_paper LONGTEXT;
  DECLARE no_price_id BIGINT;
  DECLARE with_price_id BIGINT;
  DECLARE duplicate_count INT DEFAULT 0;
  DECLARE tenant_count INT DEFAULT 0;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET no_price_json = CONVERT(FROM_BASE64(
    CONCAT(
      '',
      '',
      '',
      '',
      '',
      ''
    )
  ) USING utf8mb4);
  SET with_price_json = CONVERT(FROM_BASE64(
    CONCAT(
      '',
      '',
      '',
      '',
      '',
      '',
      ''
    )
  ) USING utf8mb4);

  IF JSON_VALID(no_price_json) <> 1 OR JSON_VALID(with_price_json) <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '调拨出库打印模板 JSON 校验失败';
  END IF;

  SELECT COUNT(*) INTO tenant_count
  FROM system_tenant
  WHERE id = 1 AND deleted = b'0';
  IF tenant_count <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '目标租户 1 不存在或已删除';
  END IF;

  SELECT COUNT(*) INTO duplicate_count
  FROM (
    SELECT name
    FROM erp_print_template
    WHERE module_key = 'stock_transfer_out'
      AND tenant_id = 1
      AND deleted = b'0'
      AND name IN ('调拨出库单-无价', '调拨出库单-带价')
    GROUP BY name
    HAVING COUNT(*) > 1
  ) duplicate_templates;
  IF duplicate_count > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '调拨出库同名打印模板存在重复，请先人工核对';
  END IF;

  SET no_price_paper = JSON_OBJECT(
    'columns', JSON_EXTRACT(no_price_json, '$.columns'),
    'columnWidths', JSON_EXTRACT(no_price_json, '$.columnWidths'),
    'rowHeights', JSON_EXTRACT(no_price_json, '$.rowHeights'),
    'rowCount', JSON_EXTRACT(no_price_json, '$.rowCount'),
    'paper', JSON_EXTRACT(no_price_json, '$.paper')
  );
  SET with_price_paper = JSON_OBJECT(
    'columns', JSON_EXTRACT(with_price_json, '$.columns'),
    'columnWidths', JSON_EXTRACT(with_price_json, '$.columnWidths'),
    'rowHeights', JSON_EXTRACT(with_price_json, '$.rowHeights'),
    'rowCount', JSON_EXTRACT(with_price_json, '$.rowCount'),
    'paper', JSON_EXTRACT(with_price_json, '$.paper')
  );

  START TRANSACTION;

  SET no_price_id = (
    SELECT MIN(id)
    FROM erp_print_template
    WHERE module_key = 'stock_transfer_out'
      AND tenant_id = 1
      AND deleted = b'0'
      AND name = '调拨出库单-无价'
  );
  INSERT INTO erp_print_template
    (module_key, name, defaulted, status, template_json, paper_config,
     creator, create_time, updater, update_time, deleted, tenant_id)
  SELECT
    'stock_transfer_out', '调拨出库单-无价', b'0', 0, no_price_json, no_price_paper,
    '1', NOW(), '1', NOW(), b'0', 1
  WHERE no_price_id IS NULL;
  SET no_price_id = COALESCE(no_price_id, LAST_INSERT_ID());

  SET with_price_id = (
    SELECT MIN(id)
    FROM erp_print_template
    WHERE module_key = 'stock_transfer_out'
      AND tenant_id = 1
      AND deleted = b'0'
      AND name = '调拨出库单-带价'
  );
  INSERT INTO erp_print_template
    (module_key, name, defaulted, status, template_json, paper_config,
     creator, create_time, updater, update_time, deleted, tenant_id)
  SELECT
    'stock_transfer_out', '调拨出库单-带价', b'0', 0, with_price_json, with_price_paper,
    '1', NOW(), '1', NOW(), b'0', 1
  WHERE with_price_id IS NULL;
  SET with_price_id = COALESCE(with_price_id, LAST_INSERT_ID());

  UPDATE erp_print_template
  SET name = '调拨出库单-无价',
      status = 0,
      template_json = no_price_json,
      paper_config = no_price_paper,
      updater = '1',
      update_time = NOW()
  WHERE id = no_price_id
    AND module_key = 'stock_transfer_out'
    AND tenant_id = 1
    AND deleted = b'0';

  UPDATE erp_print_template
  SET name = '调拨出库单-带价',
      status = 0,
      template_json = with_price_json,
      paper_config = with_price_paper,
      updater = '1',
      update_time = NOW()
  WHERE id = with_price_id
    AND module_key = 'stock_transfer_out'
    AND tenant_id = 1
    AND deleted = b'0';

  UPDATE erp_print_template
  SET defaulted = b'0',
      updater = '1',
      update_time = NOW()
  WHERE module_key = 'stock_transfer_out'
    AND tenant_id = 1
    AND deleted = b'0'
    AND defaulted = b'1'
    AND id <> no_price_id;

  UPDATE erp_print_template
  SET defaulted = b'1',
      updater = '1',
      update_time = NOW()
  WHERE id = no_price_id
    AND module_key = 'stock_transfer_out'
    AND tenant_id = 1
    AND deleted = b'0';

  COMMIT;
END$$

DELIMITER ;

CALL apply_erp_stock_transfer_out_print_templates_v277();
DROP PROCEDURE IF EXISTS apply_erp_stock_transfer_out_print_templates_v277;

SELECT id, module_key, name, defaulted + 0 AS defaulted, status, tenant_id,
       JSON_VALID(template_json) AS template_json_valid,
       JSON_UNQUOTE(JSON_EXTRACT(template_json, '$.paper.size')) AS paper_size,
       JSON_UNQUOTE(JSON_EXTRACT(template_json, '$.cells[0].fontFamily')) AS title_font,
       JSON_UNQUOTE(JSON_EXTRACT(template_json, '$.cells[0].fontSize')) AS title_font_size,
       JSON_SEARCH(template_json, 'one', '%调入部门%') AS to_dept_label_path,
       JSON_SEARCH(template_json, 'one', 'items.pieceCount') AS piece_count_path,
       JSON_SEARCH(template_json, 'one', 'document.totalPriceFormatted') AS total_amount_path
FROM erp_print_template
WHERE module_key = 'stock_transfer_out'
  AND tenant_id = 1
  AND deleted = b'0'
ORDER BY defaulted DESC, id;

